class PerimeterPolygon
  [public static]
  perimeterPolygon(s: int, l: int): int
    sum: int := 0;
    count: int := 0;
    for (i: int := 0; i < s; i++)
      for (j: int := 0; j < l; j++)
        if (s % 2 == 0 || l % 2 == 0)
          sum := sum + 1
        end if;
        count++
      end for
    end for;
    return count
  end method
end class

