class Last
  [public static]
  last(arr: List<int>, x: int, n: int): int
    if (n <= 0)
      return -1
    end if;
    for (i: int := arr.size() - 1; i >= 0; i--)
      if (arr.get(i).equals(x))
        return i
      end if
    end for;
    return -1
  end method
end class

