class CountRotation
  [public static]
  countRotation(arr: List<int>, n: int): int
    count: int := 0;
    l: int := 0;
    r: int := n - 1;
    while (l < r)
      m: int := l + (r - l) / 2;
      if (arr.get(m) <= arr.get(r))
        r := m
      else
        l := m + 1
      end if;
      count := count + (r - l + 1) / n + 1
    end while;
    return count
  end method
end class

