class IsPerfectSquare
  [public static]
  isPerfectSquare(n: int): bool
    if (n == 0 || n == 1)
      return true
    end if;
    count: int := 0;
    while (n % 2 == 0)
      count++;
      n := n / 2
    end while;
    return count == 2 || count == 3 || count == 5
  end method
end class

