class FirstOdd
  [public static]
  firstOdd(nums: List<int>): int
    count: int := 0;
    count1: int := 1;
    count2: int := 0;
    odd: bool := true;
    for (i: int := 0; i < nums.size(); i++)
      if (odd && i % 2 == 0)
        count++
      else
        count2++
      end if;
      odd := false
    end for;
    return (count % count1 == 0) ? count : count1
  end method
end class

