class MaxSubArraySum
  [public static]
  maxSubArraySum(a: List<int>, size: int): int
    max: int := 0;
    currentSum: int := 0;
    tempMax: int := 0;
    for (i: int := 0; i < a.size(); i++)
      currentSum := currentSum + a.get(i);
      tempMax := Math.max(tempMax, currentSum);
      max := Math.max(max, tempMax - currentSum);
      if (currentSum >= size)
        currentSum := tempMax
      end if
    end for;
    return max
  end method
end class

