class MinSwaps
  [public static]
  minSwaps(s1: string, s2: string): int
    count: int := 0;
    n: int := s1.length();
    m: int := s2.length();
    map: int[] := new int[n + 1];
    for (i: int := 1; i <= n; i++)
      map[i] := map[i - 1] + ((s1.charAt(i - 1) == s2.charAt(i - 1)) ? 0 : 1)
    end for;
    for (i: int := 1; i <= m; i++)
      if (map[i] == 1)
        count++
      end if
    end for;
    return count
  end method
