class FindDigits
  [public static]
  findDigits(n: int): int
    if (n < 0)
      return 0
    end if;
    if (n <= 1)
      return 1
    end if;
    x: double := (n * Math.log10(n / Math.E) + Math.log10(2 * Math.PI * n) / 2);
    return (int) Math.floor(x) + 1
  end method
end class

