class FindPlatform
  [public static]
  findPlatform(arr: List<int>, dep: List<int>, n: int): int
    plat_needed: int := 0;
    result: int := 1;
    i: int := 0;
    j: int := 0;
    while (i < n && j < n)
      if (arr.get(i) <= dep.get(j))
        plat_needed := plat_needed + 1;
        i := i + 1
      else
        if (arr.get(i) > dep.get(j))
          plat_needed := plat_needed - 1;
          j := j + 1
        end if
      end if;
      if (plat_needed > result)
        result := plat_needed
      end if
    end while;
    return result
  end method
end class

