class Sum
  [public static]
  sum(n: int): int
    sum: int := 0;
    for (i: int := 2; i <= n; i++)
      if (n % i == 0)
        sum := sum + i;
        while (n % i == 0)
          n := n / i
        end while
      end if
    end for;
    return sum
  end method
end class

