class IsTriangleexists
  [public static]
  isTriangleexists(a: int, b: int, c: int): bool
    x: int := a + b;
    y: int := c + a;
    z: int := b + c;
    count: int := 0;
    while (x > 0 && y > 0 && z > 0)
      if (x % 2 == 0 && y % 2 == 0 && z % 2 == 0)
        count++
      end if;
      x := x / 2;
      y := y / 2;
      z := z / 2
    end while;
    return count == 1
  end method
end class

