class FindMinSwaps
  [public static]
  findMinSwaps(arr: List<int>, n: int): int
    l: int := 0;
    r: int := n - 1;
    minSwaps: int := 0;
    while (l < r)
      curr: int := arr.get(l) + arr.get(r);
      minSwaps := minSwaps + curr - Math.min(arr.get(l), arr.get(r));
      if (arr.get(l) > arr.get(r))
        r--
      else
        l++
      end if
    end while;
    return minSwaps
  end method
end class

