class RemoveListRange
  [public static]
  removeListRange(list1: List<List<int>>, leftrange: int, rigthrange: int): List<List<int>>
    result: List<List<int>> := new List<>();
    if (leftrange > rigthrange)
      result.add(list1.get(0));
      return result
    end if;
    for (i: int := 0; i < list1.size(); i++)
      if (list1.get(i).size() == 0)
        continue
      end if;
      if (list1.get(i).get(0) >= leftrange && list1.get(i).get(0) <= rigthrange)
        result.add(list1.get(i))
      end if
    end for;
    return result
