class MinDifference
  [public static]
  minDifference(testList: List<List<int>>): int
    min: int := Integer.MAX_VALUE;
    for (i: int := 0; i < testList.size(); i++)
      for (j: int := 0; j < testList.get(i).size() - 1; j++)
        min := Math.min(min, Math.abs(testList.get(i).get(j) - testList.get(i).get(j + 1)))
      end for
    end for;
    return min
  end method
end class

